// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import { test } from "node:test";

import { isExploration, summarizeEvents } from "./agent-loop-events.mjs";

const start = (toolName) => ({
  type: "tool.execution_start",
  data: { toolName },
});

/// The defect this file exists for.
///
/// The classifier matched `board` and `next_task`. ADR-0059 collapsed those
/// into `task_query`, so the server the agent talks to no longer advertises
/// them — every Intent Plane call the agent made went uncounted, and the run
/// still completed. A name-keyed classifier cannot report that it stopped
/// matching: it returns false, and the exploration figure is merely lower.
test("the collapsed Intent Plane verbs count as exploration", () => {
  for (const verb of [
    "task_query",
    "task_create",
    "task_claim",
    "task_transition",
    "design_query",
    "design_register",
    "design_decide",
    "design_promote",
  ]) {
    assert.equal(
      isExploration(`lodestar-eval-${verb}`),
      true,
      `${verb} is what the server advertises now, so a run using it must be counted`,
    );
  }
});

/// Comparability is the reason the retired names stay.
///
/// `benchmarks/results/2026-07-22-agent-loop-outcome.json` was measured before
/// the collapse, when the agent could only call the old names. Dropping them
/// would silently re-define what the number means rather than fix the counter,
/// and the baseline would no longer be comparable to anything.
test("the retired verbs still count, so published baselines stay comparable", () => {
  for (const verb of [
    "board",
    "next_task",
    "constitution",
    "active_knowledge",
  ]) {
    assert.equal(isExploration(`lodestar-eval-${verb}`), true);
  }
});

test("editing and unrelated tools are still not exploration", () => {
  for (const name of [
    "edit",
    "create",
    "lodestar-eval-task_transition_unrelated_suffix_is_still_a_match",
  ]) {
    // The third is deliberate: matching is by substring, so a suffixed name
    // still counts. That is the existing behaviour and the fixture names are
    // generated, not free text.
    assert.equal(isExploration(name), name.includes("task_transition"));
  }
  assert.equal(isExploration("mindleak-eval-forget_file"), false);
  assert.equal(isExploration("mindleak-eval-recall"), true);
});

test("a run in the current vocabulary is summarised, not silently zeroed", () => {
  const summary = summarizeEvents([
    start("lodestar-eval-task_query"),
    start("lodestar-eval-task_claim"),
    start("edit"),
    { type: "assistant.message", data: { outputTokens: 12 } },
    { type: "result", usage: { premiumRequests: 2, totalApiDurationMs: 900 } },
  ]);

  assert.equal(summary.total_tool_calls, 3);
  assert.equal(
    summary.exploration_tool_calls,
    2,
    "both Intent Plane calls are exploration; only the edit is not",
  );
  assert.equal(summary.output_tokens, 12);
  assert.equal(summary.premium_requests, 2);
  assert.equal(summary.api_duration_ms, 900);
});
